import React from "react";
import { Link } from "react-router-dom";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

import "./Dashboard.css";


// ===============================
// CHART DATA
// ===============================

const feeData = [
  { day: "Monday", online: 14, offline: 13 },
  { day: "Tuesday", online: 17, offline: 12 },
  { day: "Wednesday", online: 6, offline: 22 },
  { day: "Thursday", online: 16, offline: 7 },
  { day: "Friday", online: 12, offline: 12 },
  { day: "Saturday", online: 17, offline: 14 },
  { day: "Sunday", online: 21, offline: 11 },
];

const expenseData = [
  { day: "Monday", online: 12, offline: 9 },
  { day: "Tuesday", online: 17, offline: 12 },
  { day: "Wednesday", online: 6, offline: 21 },
  { day: "Thursday", online: 15, offline: 7 },
  { day: "Friday", online: 12, offline: 11 },
  { day: "Saturday", online: 17, offline: 13 },
  { day: "Sunday", online: 20, offline: 11 },
];


// ===============================
// DASHBOARD
// ===============================

function Dashboard() {
  return (
    <div className="dashboard-container">

      {/* =====================================================
          SIDEBAR
      ====================================================== */}

      <aside className="sidebar">

        <div className="logo">
          LOGO
        </div>

        <div className="menu-section">

          <p className="menu-title">
            MAIN
          </p>

          <Link
            to="/dashboard"
            className="menu-item active"
          >
            <span>▦</span>
            Dashboard
          </Link>


          {/* CLASS */}

          <Link to="#" className="menu-item">
            <span>🎓</span>
            Class
          </Link>

          <Link to="/ViewAllClass" className="submenu-item">
            View All Class
          </Link>

          <Link to="#" className="submenu-item">
            Add New Class
          </Link>


          {/* SUBJECT */}

          <Link to="#" className="menu-item">
            <span>📚</span>
            Subject
          </Link>

          <Link to="#" className="submenu-item">
            All Class & Subjects
          </Link>

          <Link to="#" className="submenu-item">
            Add & Assign Subjects
          </Link>


          {/* STUDENTS */}

          <Link to="#" className="menu-item">
            <span>👨‍🎓</span>
            Students
          </Link>

          <Link to="#" className="submenu-item">
            Student Admission
          </Link>

          <Link to="#" className="submenu-item">
            All Student List
          </Link>


          {/* EMPLOYEE */}

          <Link to="#" className="menu-item">
            <span>👨‍💼</span>
            Employee
          </Link>

          <Link to="#" className="submenu-item">
            Add Employee
          </Link>

          <Link to="#" className="submenu-item">
            View All Employee
          </Link>

          <Link to="#" className="submenu-item">
            Job Letter
          </Link>


          {/* ATTENDANCE */}

          <Link to="#" className="menu-item">
            <span>🗓️</span>
            Attendance
          </Link>

          <Link to="#" className="submenu-item">
            Student Attendance
          </Link>

          <Link to="#" className="submenu-item">
            Employee Attendance
          </Link>


          {/* FEES */}

          <Link to="#" className="menu-item">
            <span>💰</span>
            Fees Collection
          </Link>

          <Link to="#" className="submenu-item">
            View Student Fees
          </Link>

          <Link to="#" className="submenu-item">
            Fees Collection Report
          </Link>


          {/* ACADEMICS */}

          <Link to="#" className="menu-item">
            <span>📖</span>
            Academics
          </Link>

          <Link to="#" className="submenu-item">
            Create Subjects
          </Link>

          <Link to="#" className="submenu-item">
            Assign Subject
          </Link>


          {/* TIME TABLE */}

          <Link to="#" className="menu-item">
            <span>⏰</span>
            Time Table
          </Link>

          <Link to="#" className="submenu-item">
            Create Time Table
          </Link>

          <Link to="#" className="submenu-item">
            View Time Table
          </Link>


          {/* LOGOUT */}

          <Link
            to="/login"
            className="menu-item logout"
          >
            <span>↪</span>
            Logout
          </Link>

        </div>

      </aside>


      {/* =====================================================
          MAIN CONTENT
      ====================================================== */}

      <main className="main-content">


        {/* ===================================================
            TOPBAR
        ==================================================== */}

        <header className="topbar">

          <div className="search-box">

            <input
              type="text"
              placeholder="Search from courses..."
            />

            <span>⌕</span>

          </div>


          <div className="topbar-right">

            <span className="notification">
              🔔
              <small></small>
            </span>


            <div className="profile">

              <div className="profile-avatar">
                👤
              </div>

              <span>User</span>

              <span>⌄</span>

            </div>

          </div>

        </header>



        {/* ===================================================
            PAGE HEADING
        ==================================================== */}

        <div className="page-heading">

          <span>▦</span>

          <h2>
            Dashboard
          </h2>

        </div>


        {/* ===================================================
            NEW STATISTICS SECTION
        ==================================================== */}

        <section className="statistics-grid">


          {/* TOTAL STUDENTS */}

          <div className="stat-card students-stat">

            <div className="stat-icon">
              👨‍🎓
            </div>

            <div>

              <p>
                Total Students
              </p>

              <h2>
                1000
              </h2>

              <span>
                +12% this month
              </span>

            </div>

          </div>


          {/* TOTAL EMPLOYEES */}

          <div className="stat-card employee-stat">

            <div className="stat-icon">
              👨‍💼
            </div>

            <div>

              <p>
                Total Employees
              </p>

              <h2>
                100
              </h2>

              <span>
                +5% this month
              </span>

            </div>

          </div>


          {/* WORKING STAFF */}

          <div className="stat-card staff-stat">

            <div className="stat-icon">
              👥
            </div>

            <div>

              <p>
                Working Staff
              </p>

              <h2>
                19
              </h2>

              <span>
                Active staff
              </span>

            </div>

          </div>


          {/* TOTAL INCOME */}

          <div className="stat-card income-stat">

            <div className="stat-icon">
              💰
            </div>

            <div>

              <p>
                Total Income
              </p>

              <h2>
                ₹19,00,000
              </h2>

              <span>
                +18% this month
              </span>

            </div>

          </div>

        </section>



        {/* ===================================================
            WELCOME + ATTENDANCE
        ==================================================== */}

        <section className="top-grid">


          {/* WELCOME */}

          <div className="welcome-card">

            <div>

              <h1>
                Hello <span>Tejas,</span>
              </h1>

              <h3>
                Welcome back!
              </h3>

              <p>
                We're here to guide you every step of the way.
                <br />

                Explore your learning path, track your progress,
                <br />

                and stay focused on your goals.
              </p>

              <p>
                Your journey of learning and growth continues today.
              </p>

            </div>


            <div className="welcome-illustration">
              🎓
            </div>

          </div>



          {/* ATTENDANCE */}

          <div className="attendance-card">

            <div className="card-heading">

              <h3>
                Attendance
              </h3>

              <span>
                •••
              </span>

            </div>


            <div className="attendance-legend">

              <span>
                <i className="present-dot"></i>
                Present
              </span>

              <span>
                <i className="absent-dot"></i>
                Absent
              </span>

            </div>


            <div className="donut-chart">

              <div className="donut-inner">
                80%
              </div>

            </div>


            <div className="attendance-footer">

              <button>
                ▣ April 2023⌄
              </button>

              <span>
                Overall Attendance
              </span>

            </div>

          </div>

        </section>



        {/* ===================================================
            QUICK ACTIONS
        ==================================================== */}

        <section className="quick-actions">

          <div className="quick-card">
            <span>📄</span>
            <p>Fees Details</p>
          </div>

          <div className="quick-card">
            <span>▣</span>
            <p>Attendance</p>
          </div>

          <div className="quick-card">
            <span>⏱️</span>
            <p>Time Table</p>
          </div>

          <div className="quick-card">
            <span>📝</span>
            <p>Exam</p>
          </div>

        </section>



        {/* ===================================================
            FEES COLLECTION CHART
        ==================================================== */}

        <section className="chart-card">

          <div className="chart-header">

            <div>

              <h3>
                Total Fees Collection
              </h3>

              <p>
                Weekly fees collection overview
              </p>

            </div>


            <select>

              <option>
                This Week
              </option>

              <option>
                This Month
              </option>

              <option>
                This Year
              </option>

            </select>

          </div>


          <div className="chart-wrapper">

            <ResponsiveContainer
              width="100%"
              height="100%"
            >

              <BarChart
                data={feeData}
                barGap={7}
              >

                <CartesianGrid
                  strokeDasharray="3 3"
                  vertical={false}
                />

                <XAxis
                  dataKey="day"
                  axisLine={false}
                  tickLine={false}
                  tick={{
                    fontSize: 10
                  }}
                />

                <YAxis
                  axisLine={false}
                  tickLine={false}
                  tick={{
                    fontSize: 10
                  }}
                />

                <Tooltip />

                <Bar
                  dataKey="online"
                  name="Online Fees"
                  fill="#2699e8"
                  barSize={12}
                  radius={[3, 3, 0, 0]}
                />

                <Bar
                  dataKey="offline"
                  name="Offline Fees"
                  fill="#aaaaf3"
                  barSize={12}
                  radius={[3, 3, 0, 0]}
                />

              </BarChart>

            </ResponsiveContainer>

          </div>

        </section>



        {/* ===================================================
            EXPENSE + CALENDAR
        ==================================================== */}

        <section className="lower-dashboard-grid">


          {/* EXPENSE CHART */}

          <div className="chart-card expense-card">

            <div className="chart-header">

              <div>

                <h3>
                  Total Expenses
                </h3>

                <p>
                  Weekly expense overview
                </p>

              </div>

              <select>

                <option>
                  This Week
                </option>

                <option>
                  This Month
                </option>

              </select>

            </div>


            <div className="expense-chart-wrapper">

              <ResponsiveContainer
                width="100%"
                height="100%"
              >

                <BarChart
                  data={expenseData}
                  barGap={4}
                >

                  <CartesianGrid
                    strokeDasharray="3 3"
                    vertical={false}
                  />

                  <XAxis
                    dataKey="day"
                    axisLine={false}
                    tickLine={false}
                    tick={{
                      fontSize: 9
                    }}
                  />

                  <YAxis
                    axisLine={false}
                    tickLine={false}
                    tick={{
                      fontSize: 9
                    }}
                  />

                  <Tooltip />

                  <Bar
                    dataKey="online"
                    name="Online Sales"
                    fill="#2499ee"
                    barSize={9}
                  />

                  <Bar
                    dataKey="offline"
                    name="Offline Sales"
                    fill="#18c98b"
                    barSize={9}
                  />

                </BarChart>

              </ResponsiveContainer>

            </div>


            <div className="chart-legend">

              <span>
                <i className="blue-dot"></i>
                Online Sales
              </span>

              <span>
                <i className="green-dot"></i>
                Offline Sales
              </span>

            </div>

          </div>



          {/* =================================================
              CALENDAR
          ================================================== */}

          <div className="calendar-card">

            <div className="section-title">

              <h3>
                Events calendar
              </h3>

              <span>
                •••
              </span>

            </div>


            <div className="calendar-month">

              <button>
                ‹
              </button>

              <span>
                September 2019
              </span>

              <button>
                ›
              </button>

            </div>


            <div className="calendar-week">

              <span>MO</span>
              <span>TU</span>
              <span>WE</span>
              <span>TH</span>
              <span>FR</span>
              <span>SA</span>
              <span>SU</span>

            </div>


            <div className="calendar-days">

              {Array.from(
                { length: 30 },
                (_, index) => (

                  <span
                    key={index}
                    className={
                      index === 8 ||
                      index === 13 ||
                      index === 24
                        ? "selected-day"
                        : ""
                    }
                  >
                    {index + 1}
                  </span>

                )
              )}

            </div>

          </div>

        </section>



        {/* ===================================================
            ANNOUNCEMENTS + MESSAGES
        ==================================================== */}

        <section className="bottom-dashboard-grid">


          {/* ANNOUNCEMENT */}

          <div className="announcement-card">

            <div className="section-title">

              <h3>
                Announcement
              </h3>

              <span>
                •••
              </span>

            </div>


            <div className="announcement">

              <div className="announcement-icon">
                📢
              </div>

              <div>

                <h4>
                  Midterm Exam
                </h4>

                <p>
                  All classes annual starts from Monday
                  <br />
                  01-04-2025 to 10-04-2025
                </p>

              </div>

            </div>


            <div className="announcement">

              <div className="announcement-icon">
                🎉
              </div>

              <div>

                <h4>
                  Holiday
                </h4>

                <p>
                  After annual exams there will be
                  <br />
                  10 days holiday.
                </p>

              </div>

            </div>


            <button className="add-button">
              + Add Announcement
            </button>

          </div>



          {/* MESSAGES */}

          <div className="messages-card">

            <div className="section-title">

              <h3>
                Messages
              </h3>

              <span>
                •••
              </span>

            </div>


            <div className="message">

              <div className="message-avatar">
                👩
              </div>

              <div>

                <h4>
                  Maria Morris
                </h4>

                <p>
                  Complete all classes attendance by tomorrow.
                </p>

              </div>

            </div>


            <div className="message">

              <div className="message-avatar">
                👤
              </div>

              <div>

                <h4>
                  Morris Gradape
                </h4>

                <p>
                  We need some time to update it.
                </p>

              </div>

            </div>


            <div className="message">

              <div className="message-avatar">
                👩
              </div>

              <div>

                <h4>
                  Maria Pedraza
                </h4>

                <p>
                  Yes we can update it by tomorrow.
                </p>

              </div>

            </div>

          </div>

        </section>

      </main>

    </div>
  );
}

export default Dashboard;
